"""Rebuild the offline layout worker from the original CRN Engine checkout.

Usage: python eng/bundle-msagl.py /path/to/crn-engine
The scientific layout and routing algorithms are unchanged. The adapter removes
Webpack loaders and replaces two runtime-generated getters with closures so the
worker runs under the application's existing Content Security Policy.
"""
import hashlib
import json
from pathlib import Path
import re
import sys

root = Path(__file__).resolve().parent.parent
source = Path(sys.argv[1]) / 'HTML5SharedGUI/MSAGL_JS/Scripts'
names = ['sharpkit_pre.js', 'jsclr.min.js', 'Microsoft.Msagl.min.js',
         'sharpkit_post.js', 'ggraph.js', 'msagl.worker.js']
texts = {name: (source / name).read_text(encoding='utf-8-sig') for name in names}
header = ('// Copyright (c) Microsoft Corporation. Licensed under the MIT License.\n'
          '// Original Visual DSD MSAGL/JS; generated by eng/bundle-msagl.py.\n'
          '// Source hashes and adaptation notes: eng/msagl-sources.json.\n')

def replace_once(text, before, after):
    assert text.count(before) == 1, before
    return text.replace(before, after)

runtime = '\n;\n'.join(texts[name] for name in names[:4])
runtime = replace_once(runtime, 'new Function("return this._Name;")',
                       'function(){return this._Name;}')
runtime = replace_once(runtime, 'new Function("return this.d."+i+";")',
                       '(function(key){return function(){return this.d[key];};})(i)')
# These generic SharpKit parsing helpers are unused by MSAGL. Keep the worker
# free of string evaluation rather than granting unsafe-eval to the application.
runtime = replace_once(runtime, 'Eval:function(code){eval(code)}',
                       'Eval:function(){throw new Error("Dynamic evaluation is disabled")}')
runtime = replace_once(runtime, 'eval(code)', 'JSON.parse(code)')
runtime = replace_once(runtime, "eval('(' + value + ')')", 'JSON.parse(value)')
assert not re.search(r'\beval\s*\(|new Function\s*\(', runtime)
(root / 'src/VisualDsd.App/Web/msagl.runtime.js').write_bytes((header + runtime).encode())

geometry = re.sub(r'^export \{[^\n]+\};\s*$', '', texts['ggraph.js'], flags=re.M)
geometry = geometry.replace('export function SetWorkerConstructor', 'function SetWorkerConstructor')
geometry = re.sub(r'^//# sourceMappingURL=.*$', '', geometry, flags=re.M)
exports = re.findall(r'^export \{ (\w+) \};', texts['ggraph.js'], flags=re.M)
worker = texts['msagl.worker.js']
worker = worker[worker.index('/** This class includes'):]
worker = worker.replace('export function handleMessage', 'function handleMessage')
worker = re.sub(r'^//# sourceMappingURL=.*$', '', worker, flags=re.M)
bundle = (header + "importScripts('./msagl.runtime.js');\n" + geometry +
          '\nvar G = {' + ','.join(exports) + '};\n' + worker)
(root / 'src/VisualDsd.App/Web/msagl.worker.js').write_bytes(bundle.encode())
manifest = {
    'origin': 'Microsoft CRN Engine / HTML5SharedGUI/MSAGL_JS/Scripts',
    'license': 'MIT; Copyright (c) Microsoft Corporation; see LICENSE',
    'adaptations': ['Classic worker instead of Webpack/raw-loader/eval bootstrap',
                    'Runtime-generated getters replaced by equivalent closures',
                    'Unused generic parsers use JSON.parse; dynamic Eval disabled'],
    'sources': {n: hashlib.sha256((source / n).read_bytes()).hexdigest() for n in names},
    'bundles': {n: hashlib.sha256((root / 'src/VisualDsd.App/Web' / n).read_bytes()).hexdigest()
                for n in ['msagl.runtime.js', 'msagl.worker.js']}
}
(root / 'eng/msagl-sources.json').write_bytes((json.dumps(manifest, indent=2) + '\n').encode())
